def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(
        value for row in grid for value in row if value != 0
    ).most_common(1)[0][0]
    colors = {
        value for row in grid for value in row
        if value not in (0, background)
    }

    boxes = {}
    for color in colors:
        cells = [
            (r, c) for r in range(h) for c in range(w)
            if grid[r][c] == color
        ]
        boxes[color] = (
            min(r for r, _ in cells), max(r for r, _ in cells),
            min(c for _, c in cells), max(c for _, c in cells)
        )

    frame = max(
        colors,
        key=lambda color: (
            (boxes[color][1] - boxes[color][0] + 1)
            * (boxes[color][3] - boxes[color][2] + 1)
        )
    )
    top, bottom, left, right = boxes[frame]
    result = [[background] * w for _ in range(h)]

    inner = None
    for color in colors - {frame}:
        t, b, l, r = boxes[color]
        if top <= t and b <= bottom and left <= l and r <= right:
            inner = color
            break

    if inner is not None:
        t, b, l, r = boxes[inner]
        if t == b and l == r:
            for rr in range(top, bottom + 1):
                for cc in range(left, right + 1):
                    result[rr][cc] = frame
            for rr in ((top + bottom) // 2, (top + bottom + 1) // 2):
                for cc in ((left + right) // 2, (left + right + 1) // 2):
                    result[rr][cc] = inner
        else:
            for rr in range(top, bottom + 1):
                for cc in range(left, right + 1):
                    result[rr][cc] = (
                        frame
                        if rr in (top, bottom) or cc in (left, right)
                        else inner
                    )
    else:
        for rr in range(top, bottom + 1):
            for cc in range(left, right + 1):
                result[rr][cc] = frame
        if bottom - top + 1 >= 8 and right - left + 1 >= 8:
            for rr in ((top + bottom) // 2, (top + bottom + 1) // 2):
                for cc in ((left + right) // 2, (left + right + 1) // 2):
                    result[rr][cc] = 0
        else:
            for rr in range(top + 1, bottom):
                for cc in range(left + 1, right):
                    result[rr][cc] = 0

    return result
